window.AUTH=window.AUTH||{};window.AUTH["22-196"]={"d":"22-196","id":"2022/22-196","n":"Samia v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Adam Samia","date":"2023-01-25","url":"https://www.supremecourt.gov/DocketPDF/22/22-196/253104/20230125102002705_22-196_meritsbrief.pdf","side":"pet","n":39},{"k":"respondent","label":"Brief of respondent United States of America","date":"2023-02-24","url":"https://www.supremecourt.gov/DocketPDF/22/22-196/255599/20230224185106138_22-196bsUnitedStates.pdf","side":"res","n":46},{"k":"reply","label":"Reply of petitioner Adam Samia","date":"2023-03-17","url":"https://www.supremecourt.gov/DocketPDF/22/22-196/259283/20230317100755127_22-196_meritsreply.pdf","side":"pet","n":18}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r46_dc8f.pdf","tr":true,"items":[{"t":"case","label":"Alford v. United States","cite":"282 U.S. 687","y":1931,"id":"scdb/1930-106","sc":1,"sum":"1. Cross-examination of a witness is a matter of right. P. G91.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Bruton v. United States","cite":"391 U.S. 123","y":1968,"id":"1967/705","sc":1,"op":72,"ar":52,"sum":"The Supreme Court held that Bruton was substantially prejudiced against because of the high risk that the jury considered Evans’ confession when deciding Bruton’s guilt. Admitting Evans’ confession into evidence violated Bruton’s Sixth Amendment right to cross-examination. This decision expressly overruled Delli Paoli v. United States .","sumSrc":"Oyez","by":{"0":"2, 5, 14, 18, 20-23, 28-31","1":"5, 10, 11, 13, 14, 20, 21","2":"1-10, 12-16, 18, 20"}},{"t":"case","label":"Coy v. Iowa","cite":"487 U.S. 1012","y":1988,"id":"1987/86-6757","sc":1,"op":1,"sum":"Justice Antonin Scalia delivered the opinion of a 6-2 court. The Sixth Amendment explicitly states that the accused has the right \"to be confronted with the witnesses against him.\" The Court maintained this \"confrontation is essential to fairness.\" The screen clearly disrupted this confrontation in a way that could have biased the trial.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Crawford v. Washington","cite":"541 U.S. 36","y":2004,"id":"2003/02-9410","sc":1,"op":4,"ar":5,"sum":"The Court sided with Crawford and ruled that the Sixth Amendment's Confrontation Clause gives defendants the right to confront witnesses and cross-examine their testimony. This includes testimony police gather. The Court reasoned that the Framers intended the Confrontation Clause to prohibit out-of-court testimony as evidence against defendants.","sumSrc":"Oyez","by":{"0":"4-5, 19, 23","1":"16, 19, 35","2":"4"}},{"t":"case","label":"Cruz v. New York","cite":"481 U.S. 186","y":1987,"id":"1986/85-5939","sc":1,"op":18,"sum":"Noting that a more demanding inquiry would be needed if Bruton applied to confessions incriminating only “by connection” with later-introduced evidence.","sumSrc":"opinion","by":{"0":"5, 19, 20, 38","2":"14"}},{"t":"case","label":"Delli Paoli v. United States","cite":"352 U.S. 232","y":1957,"id":"1956/33","sc":1,"sum":"Petitioner's conviction is sustained.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 30"}},{"t":"case","label":"Giles v. California","cite":"554 U.S. 353","y":2008,"id":"2007/07-6053","sc":1,"sum":"The Court held that the forfeiture by wrongdoing exception only applies to situations where the defendant causes the witness' absence with the intention of preventing that witness from testifying at trial.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Gray v. Maryland","cite":"523 U.S. 185","y":1998,"id":"1997/96-8653","sc":1,"op":16,"sum":"Stating that co-defendant confessions are “so prejudicial that limiting instructions cannot work”.","sumSrc":"opinion","by":{"0":"6, 15, 26-28, 30, 33, 35-7, 42, 44","1":"10, 11, 13, 24-27, 29-32, 36, 38, 40, 42","2":"2, 7-12, 15, 19"}},{"t":"case","label":"Greene v. McElroy","cite":"360 U.S. 474","y":1959,"id":"1958/180","sc":1,"sum":"In the absence of explicit authorization from either the President or Congress, the Secretaries of the Armed Forces were not authorized to deprive petitioner of his job in a proceeding in which he was not afforded the safeguards of confrontation and cross-examination.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Harrington v. California","cite":"395 U.S. 250","y":1969,"id":"1968/750","sc":1,"op":1,"sum":"Apart from the cumulative nature of the confessions of the two codefendants who did not take the stand, the evidence against petitioner consisting of direct testimony as opposed to circumstantial evidence was so overwhelming that the violation of Bruton v. United States, 391 U. S. 123 (which held that the admission of a confession of a codefendant who did not take the stand deprived the defendant of his rights under …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27","1":"44"}},{"t":"case","label":"Hemphill v. New York","cite":"142 S. Ct. 681","y":2022,"id":"2021/20-637","sc":1,"sum":"The trial court’s admission—over Hemphill’s objection—of the plea allocution transcript of an unavailable witness violated Hemphill’s Sixth Amendment right to confront the witnesses against him.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 31"}},{"t":"case","label":"Jackson v. Denno","cite":"378 U.S. 368","y":1964,"id":"1963/62","sc":1,"ar":1,"sum":"The Court held that the New York procedure did not allow for a reliable determination of whether or not the confessions were voluntary. Because the judge does not rule on the issue and the jury only reports on the ultimate question of guilt or innocence, there is no way to determine whether the jury found he confession voluntary.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Kirby v. United States","cite":"174 U.S. 47","y":1899,"id":"scdb/1898-125","sc":1,"sum":"On the trial of a person charged with feloniously receiving and.having in his possession with intent to convert them to his own use, postage stamps which had been feloniously stolen, taken and carried away from a post office by three persons named, although the person so receiving them well knew that the same had been so feloniously taken, stolen and carried away, the judgment convicting the said three persons of …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Lee v. Illinois","cite":"476 U.S. 530","y":1986,"id":"1985/84-6807","sc":1,"sum":"The trial court's reliance upon the codefendant's confession as substantive evidence against petitioner violated her rights under the Confrontation Clause of the Sixth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Mattox v. United States","cite":"156 U.S. 237","y":1895,"id":"scdb/1894-087","sc":1,"sum":"Caha v. United States, 152 U. S. 211, followed in holding that the homicide-in question in this case having' been committed in December, 1S89, before the passage of the act organizing the Territory of Oklahoma, was properly cognizable in the Judicial District of Kansas.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Melendez-Diaz v. Massachusetts","cite":"557 U.S. 305","y":2009,"id":"2008/07-591","sc":1,"op":2,"ar":6,"sum":"Explaining that “the Confrontation Clause is implicated by extrajudicial statements . . . contained in formalized testimonial materials, such as affdavits, depositions, prior testimony, or confessions” (internal quotation marks omitted).","sumSrc":"opinion","by":{"0":"19"}},{"t":"case","label":"Minnesota v. Murphy","cite":"465 U.S. 420","y":1984,"id":"1983/82-827","sc":1,"op":1,"sum":"The Supreme Court held that admissions made to a probation officer about a crime unrelated to the probation are admissible in subsequent prosecution. A state may require a probationer to meet with his officer and discuss matters that may affect his probationary status, but this does not create an exception to the rule that one must assert the privilege against self-incrimination.","sumSrc":"Oyez","by":{"0":"5, 20"}},{"t":"case","label":"Nash v. United States","cite":"54 F.2d 1006","y":1932,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/54/1006/","by":{"0":"30"}},{"t":"case","label":"Roberts v. Russell","cite":"392 U.S. 294","y":1968,"id":"scdb/1967-169","sc":1,"sum":"Bruton v. United States, 391 U. S. 123, which overruled Deli Paoli v. United States, 352 U. S. 232, and held that, despite instructions to the jur. to disregard implicating statements in determining a codefendant's guilt or innocence, admission at a joint trial of a defendant's extrajudicial confession implicating a codefendant violates the codefendant's Sixth Amendment right to crossexamination, is to be applied …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Shepard v. United States","cite":"290 U.S. 96","y":1933,"id":"scdb/1933-013","sc":1,"sum":"1. To make out a dying declaration the declarant must have spoken without hope of recovery and in the shadow of impending death, and this state of mind must be exhibited in the evidence and not left to conjecture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"United States v. Barrera-Medina","cite":"139 Fed. Appx. 786","y":2005,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./139/786/","sum":"Noting, in a multidefendant case in which two defendants confessed, that the confessions could be redacted with the pronoun “we” as long as neither confession referred in any way to the third defendant.","sumSrc":"brief:0","by":{"0":"40"}},{"t":"case","label":"United States v. Bozza","cite":"365 F.2d 206","y":1966,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/365/206/","by":{"0":"30","2":"4"}},{"t":"case","label":"United States v. Hardwick","cite":"544 F.3d 565","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/544/565/","op":1,"by":{"0":"35, 39"}},{"t":"case","label":"(V) Cases—continued: United States v. Hoover","cite":"246 F.3d 1054","y":2001,"url":"https://www.courtlistener.com/c/F.3d/246/1054/","by":{"0":"32, 37, 38","2":"2"}},{"t":"case","label":"United States v. Powell","cite":"732 F.3d 361","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/732/361/","sum":"Noting that the confessing defendant’s testimony “focused the listener on what [the defendant] said, did, knew, or observed” and “did not indicate the existence of anybody else”.","sumSrc":"brief:0","by":{"0":"40"}},{"t":"case","label":"United States v. Schwartz","cite":"541 F.3d 1331","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/541/1331/","ar":1,"by":{"0":"37, 39"}},{"t":"case","label":"United States v. Straker","cite":"800 F.3d 570","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/800/570/","op":1,"ar":1,"by":{"0":"35, 39"}},{"t":"case","label":"United States v. Vega Molina","cite":"407 F.3d 511","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/407/511/","op":1,"by":{"0":"35"}},{"t":"case","label":"United States v. Veras de los Santos","cite":"184 Fed. Appx. 245","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./184/245/","sum":"Noting that “[t]he revised statement eliminated all references to the existence of a coconspirator,” only “suggest[ing] obliquely that [the confessing defendant] transferred money from [another coconspirator] to another person”.","sumSrc":"brief:0","by":{"0":"40"}},{"t":"case","label":"Zafiro v. United States","cite":"506 U.S. 534","y":1993,"id":"1992/91-6824","sc":1,"sum":"Rule 14 does not require severance as a matter of law when codefendants present \"mutually exclusive defenses.\" While the Rule recognizes that joinder, even when proper under Rule 8(b), may prejudice either a defendant or the Government, it does not make mutually exclusive defenses prejudicial perse or require severance whenever prejudice is shown. Rather, severance should be granted only if there is a serious risk …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"39, 43","2":"18"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"2, 4, 18","2":"5"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(j)","(c)(1)(A)","(c)(1)","(c)(3)(B)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"8","1":"2, 2, 4, 9"}},{"t":"usc","label":"18 U.S.C. § 956","url":"https://www.law.cornell.edu/uscode/text/18/956","subs":["(a)(1)"],"stext":{"head":"§956. Conspiracy to kill, kidnap, maim, or injure persons or damage property in a foreign country","paras":[[0,"(a)(1) Whoever, within the jurisdiction of the United States, conspires with one or more other persons, regardless of where such other person or persons are located, to commit at any place outside the United States an act that would constitute the offense of murder, kidnapping, or maiming if committed in the special maritime and territorial jurisdiction of the United States shall, if any of the conspirators commits an act within the jurisdiction of the United States to effect any object of the conspiracy, be punished as provided in subsection (a)(2)."],[0,"(2) The punishment for an offense under subsection (a)(1) of this section is—"],[1,"(A) imprisonment for any term of years or for life if the offense is conspiracy to murder or kidnap; and"],[1,"(B) imprisonment for not more than 35 years if the offense is conspiracy to maim."],[0,"(b) Whoever, within the jurisdiction of the United States, conspires with one or more persons, regardless of where such other person or persons are located, to damage or destroy specific property situated within a foreign country and belonging to a foreign government or to any political subdivision thereof with which the United States is at peace, or any railroad, canal, bridge, airport, airfield, or other public utility, public conveyance, or public structure, or any religious, educational, or cultural property so situated, shall, if any of the conspirators commits an act within the jurisdiction of the United States to effect any object of the conspiracy, be imprisoned not more than 25 years."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/956?type=usc&year=mostrecent&link-type=html"},"head":"§956. Conspiracy to kill, kidnap, maim, or injure persons or damage property in a foreign country","tname":"Crimes and Criminal Procedure","by":{"0":"8","1":"2, 4"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(h)"],"stext":{"head":"§1956. Laundering of monetary instruments","paras":[[0,"(a)(1) Whoever, knowing that the property involved in a financial transaction represents the proceeds of some form of unlawful activity, conducts or attempts to conduct such a financial transaction which in fact involves the proceeds of specified unlawful activity—"],[1,"(A)(i) with the intent to promote the carrying on of specified unlawful activity; or"],[1,"(ii) with intent to engage in conduct constituting a violation of section 7201 or 7206 of the Internal Revenue Code of 1986; or"],[1,"(B) knowing that the transaction is designed in whole or in part—"],[2,"(i) to conceal or disguise the nature, the location, the source, the ownership, or the control of the proceeds of specified unlawful activity; or"],[2,"(ii) to avoid a transaction reporting requirement under State or Federal law,"],[0,"shall be sentenced to a fine of not more than $500,000 or twice the value of the property involved in the transaction, whichever is greater, or imprisonment for not more than twenty years, or both. For purposes of this paragraph, a financial transaction shall be considered to be one involving the proceeds of specified unlawful activity if it is part of a set of parallel or dependent transactions, any one of which involves the proceeds of specified unlawful activity, and all of which are part of a single plan or arrangement."],[0,"(2) Whoever transports, transmits, or transfers, or attempts to transport, transmit, or transfer a monetary instrument or funds from a place in the United States to or through a place outside the United States or to a place in the United States from or through a place outside the United States—"],[1,"(A) with the intent to promote the carrying on of specified unlawful activity; or"],[1,"(B) knowing that the monetary instrument or funds involved in the transportation, transmission, or transfer represent the proceeds of some form of unlawful activity and knowing that such transportation, transmission, or transfer is designed in whole or in part—"],[2,"(i) to conceal or disguise the nature, the location, the source, the ownership, or the control of the proceeds of specified unlawful activity; or"],[2,"(ii) to avoid a transaction reporting requirement under State or Federal law,"],[0,"shall be sentenced to a fine of not more than $500,000 or twice the value of the monetary instrument or funds involved in the transportation, transmission, or transfer, whichever is greater, or imprisonment for not more than twenty years, or both. For the purpose of the offense described in subparagraph (B), the defendant's knowledge may be established by proof that a law enforcement officer represented the matter specified in subparagraph (B) as true, and the defendant's subsequent statements or actions indicate that the defendant believed such representations to be true."],[0,"(3) Whoever, with the intent—"],[1,"(A) to promote the carrying on of specified unlawful activity;"],[1,"(B) to conceal or disguise the nature, location, source, ownership, or control of property believed to be the proceeds of specified unlawful activity; or"],[1,"(C) to avoid a transaction reporting requirement under State or Federal law,"],[0,"conducts or attempts to conduct a financial transaction involving property represented to be the proceeds of specified unlawful activity, or property used to conduct or facilitate specified unlawful activity, shall be fined under this title or imprisoned for not more than 20 years, or both. For purposes of this paragraph and paragraph (2), the term \"represented\" means any representation made by a law enforcement officer or by another person at the direction of, or with the approval of, a Federal official authorized to investigate or prosecute violations of this section."],[0,"(b) Penalties.—"],[1,"(1) In general.—Whoever conducts or attempts to conduct a transaction described in subsection (a)(1) or (a)(3), or section 1957, or a transportation, transmission, or transfer described in subsection (a)(2), is liable to the United States for a civil penalty of not more than the greater of—"],[2,"(A) the value of the property, funds, or monetary instruments involved in the transaction; or"],[2,"(B) $10,000."],[1,"(2) Jurisdiction over foreign persons.—For purposes of adjudicating an action filed or enforcing a penalty ordered under this section, the district courts shall have jurisdiction over any foreign person, including any financial institution authorized under the laws of a foreign country, against whom the action is brought, if service of process upon the foreign person is made under the Federal Rules of Civil Procedure or the laws of the country in which the foreign person is found, and—"],[2,"(A) the foreign person commits an offense under subsection (a) involving a financial transaction that occurs in whole or in part in the United States;"],[2,"(B) the foreign person converts, to his or her own use, property in which the United States has an ownership interest by virtue of the entry of an order of forfeiture by a court of the United States; or"],[2,"(C) the foreign person is a financial institution that maintains a bank account at a financial institution in the United States."],[1,"(3) Court authority over assets.—A court may issue a pretrial restraining order or take any other action necessary to ensure that any bank account or other property held by the defendant in the United States is available to satisfy a judgment under this section."],[1,"(4) Federal receiver.—"],[2,"(A) In general.—A court may appoint a Federal Receiver, in accordance with subparagraph (B) of this paragraph, to collect, marshal, and take custody, control, and possession of all assets of the defendant, wherever located, to satisfy a civil judgment under this subsection, a forfeiture judgment under section 981 or 982, or a criminal sentence under section 1957 or subsection (a) of this section, including an order of restitution to any victim of a specified unlawful activity."],[2,"(B) Appointment and authority.—A Federal Receiver described in subparagraph (A)—"],[3,"(i) may be appointed upon application of a Federal prosecutor or a Federal or State regulator, by the court having jurisdiction over the defendant in the case;"],[3,"(ii) shall be an officer of the court, and the powers of the Federal Receiver shall include the powers set out in section 754 of title 28, United States Code; and"],[3,"(iii) shall have standing equivalent to that of a Federal prosecutor for the purpose of submitting requests to obtain information regarding the assets of the defendant—"],[4,"(I) from the Financial Crimes Enforcement Network of the Department of the Treasury; or"],[4,"(II) from a foreign country pursuant to a mutual legal assistance treaty, multilateral agreement, or other arrangement for international law enforcement assistance, provided that such requests are in accordance with the policies and procedures of the Attorney General."],[0,"(c) As used in this section—"],[1,"(1) the term \"knowing that the property involved in a financial transaction represents the proceeds of some form of unlawful activity\" means that the person knew the property involved in the transaction represented proceeds from some form, though not necessarily which form, of activity that constitutes a felony under State, Federal, or foreign law, regardless of whether or not such activity is specified in paragraph (7);"],[1,"(2) the term \"conducts\" includes initiating, concluding, or participating in initiating, or concluding a transaction;"],[1,"(3) the term \"transaction\" includes a purchase, sale, loan, pledge, gift, transfer, delivery, or other disposition, and with respect to a financial institution includes a deposit, withdrawal, transfer between accounts, exchange of currency, loan, extension of credit, purchase or sale of any stock, bond, certificate of deposit, or other monetary instrument, use of a safe deposit box, or any other payment, transfer, or delivery by, through, or to a financial institution, by whatever means effected;"],[1,"(4) the term \"financial transaction\" means (A) a transaction which in any way or degree affects interstate or foreign commerce (i) involving the movement of funds by wire or other means or (ii) involving one or more monetary instruments, or (iii) involving the transfer of title to any real property, vehicle, vessel, or aircraft, or (B) a transaction involving the use of a financial institution which is engaged in, or the activities of which affect, interstate or foreign commerce in any way or degree;"],[1,"(5) the term \"monetary instruments\" means (i) coin or currency of the United States or of any other country, travelers' checks, personal checks, bank checks, and money orders, or (ii) investment securities or negotiable instruments, in bearer form or otherwise in such form that title thereto passes upon delivery;"],[1,"(6) the term \"financial institution\" includes—"],[2,"(A) any financial institution, as defined in section 5312(a)(2) of title 31, United States Code, or the regulations promulgated thereunder; and"],[2,"(B) any foreign bank, as defined in section 1 of the International Banking Act of 1978 (12 U.S.C. 3101);"],[1,"(7) the term \"specified unlawful activity\" means—"],[2,"(A) any act or activity constituting an offense listed in section 1961(1) of this title except an act which is indictable under subchapter II of chapter 53 of title 31;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1956?type=usc&year=mostrecent&link-type=html"},"head":"§1956. Laundering of monetary instruments","tname":"Crimes and Criminal Procedure","by":{"0":"8","1":"2, 4"}},{"t":"usc","label":"18 U.S.C. § 1958","url":"https://www.law.cornell.edu/uscode/text/18/1958","subs":["(a)"],"stext":{"head":"§1958. Use of interstate commerce facilities in the commission of murder-for-hire","paras":[[0,"(a) Whoever travels in or causes another (including the intended victim) to travel in interstate or foreign commerce, or uses or causes another (including the intended victim) to use the mail or any facility of interstate or foreign commerce, with intent that a murder be committed in violation of the laws of any State or the United States as consideration for the receipt of, or as consideration for a promise or agreement to pay, anything of pecuniary value, or who conspires to do so, shall be fined under this title or imprisoned for not more than ten years, or both; and if personal injury results, shall be fined under this title or imprisoned for not more than twenty years, or both; and if death results, shall be punished by death or life imprisonment, or shall be fined not more than $250,000, or both."],[0,"(b) As used in this section and section 1959—"],[1,"(1) \"anything of pecuniary value\" means anything of value in the form of money, a negotiable instrument, a commercial interest, or anything else the primary significance of which is economic advantage;"],[1,"(2) \"facility of interstate or foreign commerce\" includes means of transportation and communication; and"],[1,"(3) \"State\" includes a State of the United States, the District of Columbia, and any commonwealth, territory, or possession of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1958?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1958. Use of interstate commerce facilities in the commission of murder-for-hire","tname":"Crimes and Criminal Procedure","by":{"0":"8","1":"2, 4"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"rule","label":"Fed. R. Crim. P. 14","url":"https://www.law.cornell.edu/rules/frcrmp/rule_14","subs":["(a)"],"by":{"0":"32","1":"43","2":"18"}},{"t":"rule","label":"Fed. R. Evid. 801","url":"https://www.law.cornell.edu/rules/fre/rule_801","subs":["(d)(2)(A)"],"by":{"0":"5, 19"}},{"t":"rule","label":"Fed. R. Evid. 807","url":"https://www.law.cornell.edu/rules/fre/rule_807","by":{"0":"12"}},{"t":"case","label":"Brown v. United States","cite":"411 U.S. 223","y":1973,"id":"1972/71-6193","sc":1,"sum":"Petitioners were convicted of transporting and conspiring to transport stolen -goods in intersfate commerce to their coconspirator, whose etail store was searched under a defective warrant while petitioners were in custody in another State. The charges against petitioners were limited to acts committed before the day of the search. At a pretrial hearing on petitioners' motion to suppress evidence seized at the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44, 47"}},{"t":"case","label":"Buchanan v. Kentucky","cite":"483 U.S. 402","y":1987,"id":"1986/85-5348","sc":1,"sum":"Petitioner was tried with a codefendant for murder and related crimes. The trial court dismissed the capital portion of petitioner's indictment. It also denied his motions in which he requested that the jury not be \"death qualified,\" and that there be two juries, one for guilt and the other for sentencing, with the first not being \"death qualified.\" \"Death qualification\" occurs when prospective jurors are excluded …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"CSX Transp., Inc. v. Hensley","cite":"556 U.S. 838","y":2009,"id":"2008/08-1034","sc":1,"sum":"The Court held that a court must provide jury instruction as to the standard for finding \"fear of cancer\" damages when requested by the defendant.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Chapman v. California","cite":"386 U.S. 18","y":1967,"id":"1966/95","sc":1,"sum":"Justice Black determined that federal law must govern the application of a state harmless error rule; the Court cannot leave the formulation of rules protecting individuals from invasion by the states to those very same states.","sumSrc":"Oyez","by":{"1":"44","2":"21"}},{"t":"case","label":"Collins v. State","cite":"5 S.W. 848","y":1887,"court":"Tex. Ct. App.","url":"https://www.courtlistener.com/c/S.W./5/848/","by":{"1":"19"}},{"t":"case","label":"Frazier v. Cupp","cite":"394 U.S. 731","y":1969,"id":"1968/643","sc":1,"sum":"Petitioner in this habeas corpus proceeding claims that his constitutional rights were violated in three respects in his trial in 1965 for murder for which he had been indicted jointly with one Rawls, who pleaded guilty. (1) The prosecutor, on the basis of previous information he had received that Rawls would testify, included in his opening statement a brief summary of Rawls' expected testimony. When Rawls was …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Greer v. Miller","cite":"483 U.S. 756","y":1987,"id":"1986/85-2064","sc":1,"sum":"The prosecutor's question concerning respondent's postarrest silence does not require reversal of the conviction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 30"}},{"t":"case","label":"Gregory v. Morris","cite":"96 U.S. 619","y":1878,"id":"scdb/1877-176","sc":1,"sum":"1. The rule of the common law, that, the lien of the vendor of personal property, to secure the payment of purchase-money, is lost by the voluntary and unconditional delivery of the property to the purchaser,.does not prevent the parties from contracting for a lien which, as between themselves, will be good after delivery.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Harris v. New York","cite":"401 U.S. 222","y":1971,"id":"1970/206","sc":1,"op":1,"sum":"In a 5-to-4 decision, the Court held that the Miranda decision did not mandate that evidence inadmissible against an accused in the prosecution's case must be barred for all purposes from the trial.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Jones v. Commonwealth","cite":"72 Va. 836","y":1878,"url":"https://www.courtlistener.com/c/Va./72/836/","op":2,"by":{"1":"19"}},{"t":"case","label":"Kansas v. Carr","cite":"577 U.S. 108","y":2016,"id":"2015/14-449","sc":1,"op":1,"sum":"The Court decided that the Eighth Amendment does not require that a jury be instructed that mitigating circumstances do not need to be proven beyond a reasonable doubt, nor does it require that the sentencing phase of a joint trial be severed.","sumSrc":"Oyez","by":{"1":"15, 20, 29, 31, 39, 43"}},{"t":"case","label":"Lakeside v. Oregon","cite":"435 U.S. 333","y":1978,"id":"1977/76-6942","sc":1,"op":1,"sum":"1. The giving by a state trial judge, over a criminal defendant's objection, of a cautionary instruction that the jury is not to draw any adverse inference from the defendant's decision not to testify in his behalf does not violate the privilege against compulsory self-incrimination guaranteed by the Fifth and Fourteenth Amendments.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Marshall v. Lonberger","cite":"459 U.S. 422","y":1983,"id":"1982/81-420","sc":1,"op":2,"sum":"The admission in the Ohio murder trial of respondent's Illinois conviction based upon a guilty plea did not deprive respondent of any federal right.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Maryland v. Shatzer","cite":"559 U.S. 98","y":2010,"id":"2009/08-680","sc":1,"sum":"The Court held that the ruling in Edwards v. Arizona does not allow for suppression of statements if a substantial period of time between the invoking one's Miranda rights and a second interrogation takes place.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Nelson v. O’Neil","cite":"402 U.S. 622","y":1971,"id":"1970/336","sc":1,"sum":"Where a codefendant takes the stand in his own defense, denies making an alleged out-of-court statement implicating the defendant, and testifies in the defendant's favor, the defendant has been denied no rights protected by the Sixth and Fourteenth Amendments and in the circumstances of this case respondent, who would have encountered greater difficulty had Runnels affirmed the -statement as his, was denied neither …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Pennsylvania Co. v. Roy","cite":"102 U.S. 451","y":1880,"id":"scdb/1880-026","sc":1,"op":3,"sum":"1. A carrier of passengers -for hire is bound to observe the utmost caution, and is-responsible to them for such injuries received in the course of their transportation as might have been avoided or guarded against by his exercise of extraordinary vigilance, aided by the highest skill.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15, 16, 34"}},{"t":"case","label":"Pointer v. Texas","cite":"380 U.S. 400","y":1965,"id":"1964/577","sc":1,"op":1,"sum":"The Court held that the Sixth Amendment's right of confrontation required Texas to allow Pointer an opportunity to confront Dillard through counsel. Justice Black declined to answer whether the Sixth Amendment required Texas to appoint counsel to represent Pointer at a preliminary hearing.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"R v. Clewes, (1830) 4 C. & P. 220","cite":"172 Eng. Rep. 678","url":"https://www.courtlistener.com/c/Eng.%20Rep./172/678/","by":{"1":"33, 34"}},{"t":"case","label":"Richardson v. Marsh","cite":"481 U.S. 200","y":1987,"id":"1986/85-1433","sc":1,"op":21,"sum":"Noting that a more demanding inquiry would be needed if Bruton applied to confessions incriminating only “by connection” with later-introduced evidence.","sumSrc":"opinion","by":{"1":"5, 10-14, 16, 20-25, 27, 29-31, 36-40, 42","2":"7, 9-14"}},{"t":"case","label":"Schneble v. Florida","cite":"405 U.S. 427","y":1972,"id":"1971/68-5009","sc":1,"sum":"Any violation of Bruton that might have occurred was harmless beyond a reasonable doubt in view of the overwhelming evidence of petitioner's guilt as manifested by his confession, which completely comported with the objective evidence, and the comparatively insignificant effect of the codefendant's admission. Pp. 429-432. 215 So. 2d 611, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44, 47"}},{"t":"case","label":"Sparf v. United States","cite":"156 U.S. 51","y":1895,"id":"scdb/1894-076","sc":1,"op":3,"sum":"If one of two persons accused of having together committed the crime of murder makes a voluntary confession in the presence of the other, under such circumstances that he would naturally have contradicted it if he did not assent, the confession is admissible in evidence against both.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"19","2":"6"}},{"t":"case","label":"Spencer v. Texas","cite":"385 U.S. 554","y":1967,"id":"1966/68","sc":1,"op":1,"sum":"Texas' use of prior convictions in the petitioners' current criminal trials did not offend the provisions of the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 38, 42, 43"}},{"t":"case","label":"State v. Workman","cite":"15 S.C. 540","y":1881,"url":"https://www.courtlistener.com/c/S.C./15/540/","op":3,"by":{"1":"19"}},{"t":"case","label":"Tennessee v. Street","cite":"471 U.S. 409","y":1985,"id":"1984/83-2143","sc":1,"op":1,"sum":"Respondent's rights under the Confrontation Clause of the Sixth Amendment were not violated by the introduction of the accomplice's confession for rebuttal purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"United States v. Ball","cite":"163 U.S. 662","y":1896,"id":"scdb/1895-270","sc":1,"op":3,"sum":"A general verdict of acquittal, in a court having jurisdiction of the canse and of the defendant, upon the issue of not guilty to an indictment undertaking to charge murder, and not objected to before verdict as insufficient In that respect, Is a bar to a subsequent indictment against him for the same killing.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18, 19","2":"6"}},{"t":"case","label":"United States v. Battiste","cite":"24 F. Cas. 1042","y":1835,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./24/1042/","by":{"1":"34"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"9"}},{"t":"case","label":"United States v. Garcia","cite":"836 F.2d 385","y":1987,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/836/385/","sum":"Finding no Bruton violation where the statement was modified to refer to the codefendant delivering drug proceeds to “someone”.","sumSrc":"brief:1","by":{"1":"26"}},{"t":"case","label":"United States v. Hasting","cite":"461 U.S. 499","y":1983,"id":"1982/81-1463","sc":1,"sum":"At respondents' trial in Federal District Court on charges of kidnaping, transporting women across state lines for immoral purposes, and conspiracy to commit such offenses, the victims' testimony included recitals concerning multiple incidents of rape and sodomy by respondents. The defense relied on a theory of consent and-inconsistently--on the possibility that the victims' identification of respondents was …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"United States v. Lyle","cite":"919 F.3d 716","y":2019,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/919/716/","by":{"1":"9"}},{"t":"case","label":"United States v. Nuñez-Rodriguez","cite":"92 F.3d 14","y":1996,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/92/14/","by":{"1":"27"}},{"t":"case","label":"United States v. Olano","cite":"507 U.S. 725","y":1993,"id":"1992/91-1306","sc":1,"op":1,"sum":"The presence of the alternate jurors during jury deliberations was not an error that the Court of Appeals was authorized to correct under Rule 52(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14"}},{"t":"case","label":"Watkins v. Sowders","cite":"449 U.S. 341","y":1981,"id":"1980/79-5949","sc":1,"sum":"The Court concluded that the Due Process Clause does not require a judicial determination of admissibility of identification, though it is advisable.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"19"}},{"t":"case","label":"Bryant v. State","cite":"565 So. 2d 1298","y":1990,"court":"Fla.","url":"https://www.courtlistener.com/c/So.%202d/565/1298/","by":{"2":"15"}},{"t":"case","label":"Davis v. State","cite":"528 S.E.2d 800","y":2000,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/528/800/","by":{"2":"15"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"State v. Boucher","cite":"718 A.2d 1092","y":1998,"court":"Me.","url":"https://www.courtlistener.com/c/A.2d/718/1092/","by":{"2":"15"}},{"t":"rule","label":"Fed. R. Evid. 403","url":"https://www.law.cornell.edu/rules/fre/rule_403","by":{"2":"18"}}]};